void CHARACTER::fishing()
{
	// MT2009_PLUS_FISHING_RENEWAL_V1 (pull): a renewal cast (the new fishing window, fish_renewal.cpp) ends here - the old take never sees it
	{
		bool Mt2009FishRenPull(LPCHARACTER ch);
		if (m_pkPreFishingEvent && Mt2009FishRenPull(this))
			return;
	}

	if (m_pkFishingEvent || m_pkPreFishingEvent)
	{

	// MT2009_PLUS_FISHING_RENEWAL_V1 (cast): the new fishing window's cast for a client that has it (fish_renewal.cpp); NULL - the bar minigame
	{
		LPEVENT Mt2009FishRenCast(LPCHARACTER ch);
		m_pkPreFishingEvent = Mt2009FishRenCast(this);
	}
	if (!m_pkPreFishingEvent)
		m_pkPreFishingEvent = fishing::CreatePreFishingEvent(this);
}

